import fs from 'node:fs';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import {execFileSync,spawnSync} from 'node:child_process';
const p=JSON.parse(fs.readFileSync('artifacts/phase3-efp-i01-post-merge-sync.json','utf8'));
const git=(...args)=>execFileSync('git',args,{encoding:'utf8',maxBuffer:32*1024*1024}).trim();
const blob=(s,f)=>execFileSync('git',['show',s+':'+f],{maxBuffer:32*1024*1024});
const hash=x=>crypto.createHash('sha256').update(x).digest('hex').toUpperCase();
const check=b=>assert.ok(b);
const bound=r=>{assert.equal(hash(blob(r.commit,r.path)),r.sha256.toUpperCase());assert.equal(git('rev-parse',r.commit+':'+r.path),r.gitBlob)};
const ancestry=(s)=>{const r=spawnSync('git',['merge-base','--is-ancestor',s,p.observedMainSha]);check([0,1].includes(r.status));return r.status===0;};
check(ancestry(p.previousMainSha));
assert.deepEqual(git('show','-s','--format=%P',p.observedMainSha).split(' '),[p.previousMainSha,p.promotionHead]);
assert.equal(git('rev-parse',p.observedMainSha+'^{tree}'),git('rev-parse',p.promotionHead+'^{tree}'));
const paths=git('diff','--name-only',p.previousMainSha+'..'+p.observedMainSha).split('\n').sort();
assert.equal(paths.length,26);assert.deepEqual(paths,p.finalBlobTable.map(r=>r.path).sort());
for(const r of p.finalBlobTable){bound(r.approved);bound(r.main);assert.equal(r.approved.gitBlob,r.main.gitBlob);}
assert.equal(p.importedSources.length,20);
for(const r of p.importedSources){assert.equal(hash(blob(r.sourceCommit,r.path)),r.sha256.toUpperCase());assert.equal(hash(blob(p.observedMainSha,r.path)),r.sha256.toUpperCase());assert.equal(git('rev-parse',r.sourceCommit+':'+r.path),r.blob);}
for(const r of p.boundArtifacts) bound(r);
for(const r of p.governanceBindings){bound(r.original);bound(r.main);assert.equal(r.original.sha256,r.main.sha256);}
for(const r of p.integrationLineage) assert.equal(ancestry(r.commit),r.ancestorOfObservedMain);
for(const r of p.sourceReviewBindings){
 assert.equal(git('rev-parse',r.review+'^'),r.candidate);
 assert.equal(hash(blob(r.review,r.path)),r.sha256.toUpperCase());
 assert.equal(hash(blob(p.observedMainSha,r.path)),r.sha256.toUpperCase());
 assert.equal(ancestry(r.candidate),r.oldCandidateAncestor);
 const review=JSON.parse(blob(r.review,r.path));
 assert.equal(review.reviewedSha,r.candidate);assert.equal(review.finalVerdict,'PASS');assert.equal(review.acceptedScope,r.scope);
}
const ra=p.integrationReview;
assert.equal(hash(blob(ra.commit,ra.path)),ra.sha256.toUpperCase());
assert.equal(git('rev-parse',ra.commit+'^'),ra.actualDirectParent);
const reviewed=JSON.parse(blob(ra.commit,ra.path));
assert.equal(reviewed.reviewedSha,ra.actualDirectParent);assert.equal(reviewed.finalVerdict,'PASS');
for(const r of p.preservedObjects){
 assert.equal(git('rev-parse',p.previousMainSha+':'+r.path),r.previousMainObject);
 assert.equal(git('rev-parse',p.observedMainSha+':'+r.path),r.observedMainObject);
 assert.equal(r.previousMainObject,r.observedMainObject);
 assert.equal(git('rev-parse','HEAD:'+r.path),r.observedMainObject);
}
for(const r of Object.values(p.github)){assert.equal(r.exitCode,0);assert.equal(hash(r.raw),r.sha256);}
const pr=JSON.parse(p.github.pr.raw);
assert.equal(pr.state,'MERGED');assert.equal(pr.mergeCommit.oid,p.observedMainSha);assert.equal(pr.headRefOid,p.promotionHead);
const runs=JSON.parse(p.github.runs.raw);
for(const r of p.mainChecks.runs){const actual=runs.find(x=>x.databaseId===r.databaseId);assert.deepEqual(actual,r);assert.equal(r.headSha,p.observedMainSha);assert.equal(r.conclusion,'success');assert.equal(r.status,'completed');}
check(p.github.testLog.raw.includes('195 passed'));
check(p.github.testLog.raw.includes('1628 passed'));
check(p.github.testLog.raw.includes('1 skipped'));
const {buildCoverageFromArchives,loadAuthoringArchives}=await import('./scripts/phase3-coverage.ts');
const generatedAt=p.coverage.freshSnapshot.generatedAt;
const fresh=buildCoverageFromArchives(loadAuthoringArchives(process.cwd()),{workspaceRoot:process.cwd(),generatedAt});
assert.deepEqual(fresh,p.coverage.freshSnapshot);
assert.deepEqual(p.coverage.before,p.coverage.after);
for(const v of Object.values(p.coverage.delta))assert.equal(v,0);
assert.equal(p.accounting.accepted,111);assert.equal(p.accounting.frozenDenominator,944);assert.equal(p.accounting.remaining,833);
assert.equal(p.accounting.acceptedIdentities.length,111);assert.equal(new Set(p.accounting.acceptedIdentities).size,111);
for(const k of ['mainCoverageCreditDelta','migrationCreditDelta','denominatorDelta'])assert.equal(p.accounting[k],0);
assert.equal(p.boundaries.newRuntimeOrGateAcceptance,false);
console.log('PASS: exact merge/tree, 26 blobs, 20 imported sources, reviews/ancestry, preserved objects, raw receipts, actual coverage, zero credit');
